body.query:
  query Article($key: String!) {
    resource(id: $key) {
      ...ResourceRedirectDetails
      ... on Article {
        ...ArticlePage
      }
    }
  }

fragment ResourceRedirectDetails on Resource {
  __typename
  ... on Article {
    id
    title
    urlAlias
  }
  ... on Composition {
    id
    maybeTitle: title
    urlAlias
  }
  ... on DataUse {
    id
    title
  }
  ... on Document {
    id
    title
  }
  ... on MeetingEvent {
    id
    title
  }
  ... on News {
    id
    title
  }
  ... on Programme {
    id
    title
  }
  ... on GbifProject {
    id
    title
  }
  ... on Tool {
    id
    title
  }
}

fragment ArticlePage on Article {
  id
  title
  summary
  excerpt
  body
  primaryImage {
    ...ArticleBanner
  }
  secondaryLinks {
    label
    url
  }
  documents {
    ...DocumentPreview
  }
  topics
  purposes
  audiences
  citation
  createdAt
}

fragment ArticleBanner on AssetImage {
  description
  title
  file {
    url
    details {
      image {
        width
        height
      }
    }
    normal: thumbor(width: 1200, height: 500)
    mobile: thumbor(width: 800, height: 400)
  }
}

fragment DocumentPreview on DocumentAsset {
  title
  file {
    url
    fileName
    contentType
    volatile_documentType
    details {
      size
    }
  }
}
